from pathlib import Path
import json, re

prod = Path.home() / "prediction_research_prod"

def sj(p):
    try:
        if not p.is_file() or p.is_symlink(): return None
        return json.loads(p.read_text())
    except Exception:
        return None

rows=[]
d=prod/"knowledge/candidates"
if d.is_dir():
    for p in sorted(d.glob("*.json")):
        x=sj(p)
        if isinstance(x,dict) and x.get("candidate_id"):
            rows.append({
                "id":x.get("candidate_id"),
                "q":x.get("queue_status"),
                "ph":x.get("phase"),
                "dec":x.get("decision"),
                "pri":x.get("priority"),
                "exp":x.get("active_experiment_ids") or [],
                "qual":bool(x.get("qualification_fixture")),
                "next":(x.get("next_decisive_test") or "")[:180],
                "upd":x.get("updated_at")
            })

active=[]
ad=prod/"candidates/active"
if ad.is_dir():
    for p in sorted(ad.glob("*")):
        if not p.is_file() or p.is_symlink(): continue
        t=p.read_text(errors="replace")
        def g(k):
            m=re.search(r"(?m)^\s*"+re.escape(k)+r":\s*[\"']?([^\"'\n#]+)",t)
            return m.group(1).strip() if m else None
        active.append({"id":g("candidate_id") or g("id"),"status":g("status"),"econ":g("economic_status"),"file":p.name})

state=sj(prod/"knowledge/codex_runtime/STATE.json")
q=sj(Path("/tmp/prediction-full-a2z-live-v4-state.json"))

out={
 "rows":rows,
 "active":active,
 "supervisor": {k:state.get(k) for k in ("state","reason","candidate_id","updated_at")} if isinstance(state,dict) else None,
 "qual_stages":[[s.get("stage"),s.get("status")] for s in (q or {}).get("stages",[])] if isinstance(q,dict) else None
}
print("INVENTORY_E003 "+json.dumps(out,separators=(",",":"),default=str),flush=True)
raise SystemExit(2)
